/* ==========================================================================
   Entire AI Test - Modern & Responsive Stylesheet
   ========================================================================== */

/* --- CSS Variables & Design Tokens --- */
:root {
  /* Color Palette - Dark Theme (Default) */
  --bg-primary: #0a0d14;
  --bg-secondary: #0f1422;
  --surface: rgba(18, 24, 38, 0.75);
  --surface-hover: rgba(26, 34, 52, 0.85);
  --surface-border: rgba(255, 255, 255, 0.08);
  --surface-border-hover: rgba(99, 102, 241, 0.4);

  --text-primary: #f8fafc;
  --text-secondary: #94a3b8;
  --text-muted: #64748b;

  --primary: #6366f1;
  --primary-hover: #4f46e5;
  --primary-light: rgba(99, 102, 241, 0.15);
  --accent-cyan: #06b6d4;
  --accent-purple: #a855f7;
  --accent-emerald: #10b981;

  --gradient-brand: linear-gradient(135deg, #6366f1 0%, #a855f7 50%, #06b6d4 100%);
  --gradient-text: linear-gradient(135deg, #ffffff 0%, #cbd5e1 50%, #94a3b8 100%);
  --gradient-hero: linear-gradient(135deg, #818cf8 0%, #c084fc 40%, #38bdf8 100%);

  --shadow-sm: 0 2px 8px rgba(0, 0, 0, 0.2);
  --shadow-md: 0 10px 30px -10px rgba(0, 0, 0, 0.5);
  --shadow-lg: 0 20px 40px -15px rgba(0, 0, 0, 0.6);
  --shadow-glow: 0 0 35px rgba(99, 102, 241, 0.25);

  --font-main: 'Plus Jakarta Sans', system-ui, -apple-system, sans-serif;
  --font-mono: 'JetBrains Mono', monospace;

  --radius-sm: 8px;
  --radius-md: 14px;
  --radius-lg: 20px;
  --radius-full: 9999px;

  --transition: all 0.25s cubic-bezier(0.16, 1, 0.3, 1);
}

/* Light Theme Variables */
[data-theme="light"] {
  --bg-primary: #f8fafc;
  --bg-secondary: #f1f5f9;
  --surface: rgba(255, 255, 255, 0.85);
  --surface-hover: rgba(255, 255, 255, 0.98);
  --surface-border: rgba(148, 163, 184, 0.2);
  --surface-border-hover: rgba(99, 102, 241, 0.5);

  --text-primary: #0f172a;
  --text-secondary: #475569;
  --text-muted: #94a3b8;

  --primary: #4f46e5;
  --primary-hover: #4338ca;
  --primary-light: rgba(79, 70, 229, 0.1);

  --gradient-brand: linear-gradient(135deg, #4f46e5 0%, #9333ea 50%, #0284c7 100%);
  --gradient-text: linear-gradient(135deg, #0f172a 0%, #334155 100%);
  --gradient-hero: linear-gradient(135deg, #4338ca 0%, #7e22ce 50%, #0284c7 100%);

  --shadow-sm: 0 2px 8px rgba(0, 0, 0, 0.05);
  --shadow-md: 0 10px 30px -10px rgba(99, 102, 241, 0.12);
  --shadow-lg: 0 20px 40px -15px rgba(99, 102, 241, 0.15);
  --shadow-glow: 0 0 35px rgba(79, 70, 229, 0.15);
}

/* --- Base Reset & Typography --- */
*, *::before, *::after {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

html {
  scroll-behavior: smooth;
  font-size: 16px;
}

body {
  font-family: var(--font-main);
  background-color: var(--bg-primary);
  color: var(--text-primary);
  line-height: 1.6;
  min-height: 100vh;
  position: relative;
  overflow-x: hidden;
  transition: background-color 0.3s ease, color 0.3s ease;
  -webkit-font-smoothing: antialiased;
}

a {
  color: inherit;
  text-decoration: none;
}

button, input {
  font-family: inherit;
  font-size: inherit;
}

/* --- Background Ambient Glows & Grid --- */
.bg-glow {
  position: fixed;
  border-radius: 50%;
  filter: blur(120px);
  pointer-events: none;
  z-index: 0;
  opacity: 0.35;
  transition: opacity 0.4s ease;
}

.bg-glow-1 {
  width: 500px;
  height: 500px;
  background: radial-gradient(circle, #6366f1, transparent 70%);
  top: -100px;
  right: -100px;
}

.bg-glow-2 {
  width: 450px;
  height: 450px;
  background: radial-gradient(circle, #06b6d4, transparent 70%);
  bottom: 10%;
  left: -120px;
}

[data-theme="light"] .bg-glow {
  opacity: 0.2;
}

.bg-grid {
  position: fixed;
  inset: 0;
  background-image: 
    linear-gradient(to right, var(--surface-border) 1px, transparent 1px),
    linear-gradient(to bottom, var(--surface-border) 1px, transparent 1px);
  background-size: 40px 40px;
  mask-image: radial-gradient(circle at center, black 40%, transparent 85%);
  -webkit-mask-image: radial-gradient(circle at center, black 40%, transparent 85%);
  pointer-events: none;
  z-index: 0;
  opacity: 0.6;
}

/* --- Layout Container --- */
.container {
  width: 100%;
  max-width: 1200px;
  margin: 0 auto;
  padding: 0 1.5rem;
  position: relative;
  z-index: 1;
}

.section {
  padding: 5.5rem 0;
}

.section-header {
  text-align: center;
  max-width: 680px;
  margin: 0 auto 3.5rem auto;
}

.section-title {
  font-size: clamp(1.8rem, 3.5vw, 2.5rem);
  font-weight: 800;
  letter-spacing: -0.025em;
  margin-bottom: 0.85rem;
  background: var(--gradient-text);
  -webkit-background-clip: text;
  -webkit-text-fill-color: transparent;
}

.section-desc {
  font-size: 1.05rem;
  color: var(--text-secondary);
}

/* --- Glassmorphism Card Style --- */
.card-glass {
  background: var(--surface);
  backdrop-filter: blur(16px);
  -webkit-backdrop-filter: blur(16px);
  border: 1px solid var(--surface-border);
  border-radius: var(--radius-lg);
  box-shadow: var(--shadow-md);
  transition: var(--transition);
}

.card-glass:hover {
  border-color: var(--surface-border-hover);
  box-shadow: var(--shadow-glow), var(--shadow-md);
}

/* --- Navigation Bar --- */
.navbar {
  position: sticky;
  top: 0;
  width: 100%;
  z-index: 100;
  background: rgba(10, 13, 20, 0.7);
  backdrop-filter: blur(16px);
  -webkit-backdrop-filter: blur(16px);
  border-bottom: 1px solid var(--surface-border);
  transition: background-color 0.3s ease, border-color 0.3s ease;
}

[data-theme="light"] .navbar {
  background: rgba(248, 250, 252, 0.8);
}

.nav-container {
  display: flex;
  align-items: center;
  justify-content: space-between;
  height: 4.5rem;
}

.brand {
  display: flex;
  align-items: center;
  gap: 0.65rem;
  font-size: 1.35rem;
  font-weight: 800;
  letter-spacing: -0.02em;
}

.brand-icon {
  display: flex;
  align-items: center;
  justify-content: center;
  width: 38px;
  height: 38px;
  border-radius: var(--radius-sm);
  background: var(--gradient-brand);
  color: #ffffff;
  box-shadow: 0 4px 14px rgba(99, 102, 241, 0.4);
}

.brand-text .highlight {
  background: var(--gradient-brand);
  -webkit-background-clip: text;
  -webkit-text-fill-color: transparent;
}

.nav-links {
  display: flex;
  align-items: center;
  gap: 2rem;
}

.nav-link {
  font-size: 0.95rem;
  font-weight: 500;
  color: var(--text-secondary);
  transition: color 0.2s ease;
  position: relative;
  padding: 0.35rem 0;
}

.nav-link::after {
  content: '';
  position: absolute;
  bottom: 0;
  left: 0;
  width: 0%;
  height: 2px;
  background: var(--gradient-brand);
  transition: width 0.25s ease;
  border-radius: 2px;
}

.nav-link:hover {
  color: var(--text-primary);
}

.nav-link:hover::after {
  width: 100%;
}

.nav-actions {
  display: flex;
  align-items: center;
  gap: 0.75rem;
}

/* --- Buttons --- */
.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 0.5rem;
  font-weight: 600;
  border-radius: var(--radius-md);
  padding: 0.75rem 1.4rem;
  cursor: pointer;
  border: 1px solid transparent;
  transition: var(--transition);
  text-decoration: none;
  font-size: 0.95rem;
}

.btn-primary {
  background: var(--gradient-brand);
  color: #ffffff;
  box-shadow: 0 4px 16px rgba(99, 102, 241, 0.35);
}

.btn-primary:hover {
  transform: translateY(-2px);
  box-shadow: 0 6px 22px rgba(99, 102, 241, 0.5);
  filter: brightness(1.1);
}

.btn-secondary {
  background: var(--surface);
  color: var(--text-primary);
  border-color: var(--surface-border);
}

.btn-secondary:hover {
  background: var(--surface-hover);
  border-color: var(--surface-border-hover);
  transform: translateY(-2px);
}

.btn-sm {
  padding: 0.5rem 1.1rem;
  font-size: 0.875rem;
  border-radius: var(--radius-sm);
}

.btn-lg {
  padding: 0.9rem 1.85rem;
  font-size: 1.05rem;
  border-radius: var(--radius-md);
}

.btn-icon {
  display: flex;
  align-items: center;
  justify-content: center;
  width: 40px;
  height: 40px;
  border-radius: var(--radius-md);
  background: var(--surface);
  border: 1px solid var(--surface-border);
  color: var(--text-secondary);
  cursor: pointer;
  transition: var(--transition);
}

.btn-icon:hover {
  color: var(--text-primary);
  border-color: var(--surface-border-hover);
  background: var(--surface-hover);
}

.mobile-menu-btn {
  display: none;
}

/* Theme Toggle Icons */
[data-theme="dark"] .icon-sun {
  display: block;
}
[data-theme="dark"] .icon-moon {
  display: none;
}
[data-theme="light"] .icon-sun {
  display: none;
}
[data-theme="light"] .icon-moon {
  display: block;
}

/* --- Hero Section --- */
.hero-section {
  padding: 5rem 0 4rem 0;
  text-align: center;
}

.hero-container {
  display: flex;
  flex-direction: column;
  align-items: center;
}

.badge-wrapper {
  margin-bottom: 1.5rem;
}

.badge {
  display: inline-flex;
  align-items: center;
  gap: 0.5rem;
  padding: 0.4rem 1rem;
  border-radius: var(--radius-full);
  background: var(--primary-light);
  border: 1px solid rgba(99, 102, 241, 0.3);
  color: var(--primary);
  font-size: 0.85rem;
  font-weight: 600;
  letter-spacing: 0.02em;
}

[data-theme="dark"] .badge {
  color: #a5b4fc;
}

.badge-dot {
  width: 8px;
  height: 8px;
  border-radius: 50%;
  background-color: var(--accent-emerald);
  box-shadow: 0 0 10px var(--accent-emerald);
  animation: pulse 2s infinite;
}

@keyframes pulse {
  0% { transform: scale(0.95); opacity: 0.8; }
  50% { transform: scale(1.2); opacity: 1; }
  100% { transform: scale(0.95); opacity: 0.8; }
}

.hero-title {
  font-size: clamp(2.75rem, 6.5vw, 4.8rem);
  font-weight: 800;
  letter-spacing: -0.035em;
  line-height: 1.1;
  margin-bottom: 1.4rem;
  background: var(--gradient-hero);
  -webkit-background-clip: text;
  -webkit-text-fill-color: transparent;
  max-width: 900px;
}

.hero-subtitle {
  font-size: clamp(1.05rem, 2vw, 1.25rem);
  color: var(--text-secondary);
  max-width: 680px;
  margin-bottom: 2.2rem;
}

.hero-cta {
  display: flex;
  align-items: center;
  gap: 1rem;
  margin-bottom: 3.5rem;
  flex-wrap: wrap;
  justify-content: center;
}

/* Floating Code Preview Card */
.hero-card-preview {
  width: 100%;
  max-width: 720px;
  perspective: 1000px;
}

.code-card {
  text-align: left;
  overflow: hidden;
  border-radius: var(--radius-lg);
  border-color: rgba(99, 102, 241, 0.25);
}

.card-header-bar {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 0.75rem 1.25rem;
  background: rgba(0, 0, 0, 0.2);
  border-bottom: 1px solid var(--surface-border);
}

[data-theme="light"] .card-header-bar {
  background: rgba(0, 0, 0, 0.04);
}

.dots {
  display: flex;
  gap: 6px;
}

.dot {
  width: 11px;
  height: 11px;
  border-radius: 50%;
}

.dot-red { background: #ef4444; }
.dot-yellow { background: #f59e0b; }
.dot-green { background: #10b981; }

.code-title {
  font-size: 0.85rem;
  font-family: var(--font-mono);
  color: var(--text-muted);
}

.status-indicator {
  font-size: 0.75rem;
  font-weight: 600;
  color: var(--accent-emerald);
  padding: 0.2rem 0.55rem;
  border-radius: var(--radius-full);
  background: rgba(16, 185, 129, 0.15);
}

.code-content {
  padding: 1.4rem 1.5rem;
  font-family: var(--font-mono);
  font-size: 0.88rem;
  line-height: 1.7;
  overflow-x: auto;
}

.code-keyword { color: #f43f5e; font-weight: 600; }
.code-var { color: #60a5fa; }
.code-prop { color: #a78bfa; }
.code-str { color: #34d399; }
.code-bool { color: #fbbf24; }
.code-num { color: #f97316; }
.code-comment { color: #64748b; font-style: italic; }
.code-func { color: #38bdf8; }

/* --- Features Grid --- */
.features-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(260px, 1fr));
  gap: 1.5rem;
}

.feature-card {
  padding: 2.2rem 1.8rem;
  display: flex;
  flex-direction: column;
}

.feature-icon-box {
  width: 52px;
  height: 52px;
  border-radius: var(--radius-md);
  background: var(--primary-light);
  color: var(--primary);
  display: flex;
  align-items: center;
  justify-content: center;
  margin-bottom: 1.3rem;
  transition: var(--transition);
}

[data-theme="dark"] .feature-icon-box {
  color: #818cf8;
}

.feature-card:hover .feature-icon-box {
  background: var(--gradient-brand);
  color: #ffffff;
  transform: scale(1.08) rotate(3deg);
}

.feature-card h3 {
  font-size: 1.25rem;
  font-weight: 700;
  margin-bottom: 0.65rem;
  letter-spacing: -0.015em;
}

.feature-card p {
  color: var(--text-secondary);
  font-size: 0.95rem;
  line-height: 1.6;
}

/* --- Interactive AI Playground --- */
.playground-card {
  padding: 2rem;
  max-width: 860px;
  margin: 0 auto;
}

.playground-presets {
  display: flex;
  align-items: center;
  gap: 0.6rem;
  flex-wrap: wrap;
  margin-bottom: 1.5rem;
}

.preset-label {
  font-size: 0.85rem;
  color: var(--text-muted);
  font-weight: 600;
}

.chip {
  padding: 0.4rem 0.85rem;
  border-radius: var(--radius-full);
  font-size: 0.825rem;
  font-weight: 500;
  background: var(--surface);
  border: 1px solid var(--surface-border);
  color: var(--text-secondary);
  cursor: pointer;
  transition: var(--transition);
}

.chip:hover {
  background: var(--primary-light);
  border-color: var(--primary);
  color: var(--primary);
  transform: translateY(-1px);
}

.chat-window {
  background: rgba(0, 0, 0, 0.2);
  border: 1px solid var(--surface-border);
  border-radius: var(--radius-md);
  padding: 1.4rem;
  min-height: 250px;
  max-height: 380px;
  overflow-y: auto;
  display: flex;
  flex-direction: column;
  gap: 1.2rem;
  margin-bottom: 1.25rem;
}

[data-theme="light"] .chat-window {
  background: rgba(0, 0, 0, 0.02);
}

.chat-message {
  display: flex;
  gap: 0.9rem;
  max-width: 85%;
  animation: fadeIn 0.3s ease;
}

@keyframes fadeIn {
  from { opacity: 0; transform: translateY(6px); }
  to { opacity: 1; transform: translateY(0); }
}

.bot-message {
  align-self: flex-start;
}

.user-message {
  align-self: flex-end;
  flex-direction: row-reverse;
}

.avatar {
  width: 34px;
  height: 34px;
  border-radius: var(--radius-sm);
  display: flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
  background: var(--primary-light);
  color: var(--primary);
}

.user-message .avatar {
  background: var(--accent-purple);
  color: #fff;
}

.message-bubble {
  background: var(--surface);
  border: 1px solid var(--surface-border);
  padding: 0.85rem 1.15rem;
  border-radius: var(--radius-md);
  font-size: 0.95rem;
  color: var(--text-primary);
  line-height: 1.6;
}

.user-message .message-bubble {
  background: var(--primary);
  color: #ffffff;
  border-color: transparent;
}

.typing-cursor {
  display: inline-block;
  width: 6px;
  height: 15px;
  background: var(--primary);
  margin-left: 4px;
  vertical-align: middle;
  animation: blink 0.8s infinite;
}

@keyframes blink {
  0%, 100% { opacity: 1; }
  50% { opacity: 0; }
}

.prompt-form {
  width: 100%;
}

.input-group {
  display: flex;
  gap: 0.75rem;
  background: var(--surface);
  border: 1px solid var(--surface-border);
  border-radius: var(--radius-md);
  padding: 0.4rem 0.5rem 0.4rem 1rem;
  transition: var(--transition);
}

.input-group:focus-within {
  border-color: var(--primary);
  box-shadow: 0 0 0 3px var(--primary-light);
}

.input-group input {
  flex: 1;
  background: transparent;
  border: none;
  outline: none;
  color: var(--text-primary);
  font-size: 0.95rem;
}

.input-group input::placeholder {
  color: var(--text-muted);
}

/* --- Stats Section --- */
.stats-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(200px, 1fr));
  gap: 1.5rem;
}

.stat-item {
  padding: 2.2rem 1.5rem;
  text-align: center;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
}

.stat-number {
  font-size: 3rem;
  font-weight: 800;
  display: inline-block;
  line-height: 1;
  background: var(--gradient-brand);
  -webkit-background-clip: text;
  -webkit-text-fill-color: transparent;
}

.stat-suffix {
  font-size: 1.5rem;
  font-weight: 700;
  color: var(--primary);
  display: inline-block;
  margin-top: -2.8rem;
  margin-left: 0.2rem;
  align-self: flex-end;
}

.stat-label {
  margin-top: 1rem;
  font-size: 0.95rem;
  font-weight: 600;
  color: var(--text-secondary);
}

/* --- About Section --- */
.about-card {
  padding: 3rem 2.5rem;
  max-width: 900px;
  margin: 0 auto;
}

.about-badge {
  display: inline-block;
  font-size: 0.8rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.08em;
  color: var(--primary);
  margin-bottom: 0.75rem;
}

.about-content h2 {
  font-size: 2rem;
  font-weight: 800;
  margin-bottom: 1.1rem;
  letter-spacing: -0.02em;
}

.about-content p {
  color: var(--text-secondary);
  font-size: 1.05rem;
  line-height: 1.7;
  margin-bottom: 1.8rem;
}

.tech-tags {
  display: flex;
  flex-wrap: wrap;
  gap: 0.65rem;
}

.tag {
  background: var(--surface);
  border: 1px solid var(--surface-border);
  padding: 0.4rem 0.9rem;
  border-radius: var(--radius-md);
  font-size: 0.85rem;
  font-weight: 600;
  color: var(--text-secondary);
}

/* --- Footer --- */
.footer {
  border-top: 1px solid var(--surface-border);
  padding: 3.5rem 0 2.5rem 0;
  background: var(--bg-secondary);
}

.footer-container {
  display: flex;
  align-items: center;
  justify-content: space-between;
  flex-wrap: wrap;
  gap: 1.5rem;
}

.footer-sub {
  font-size: 0.9rem;
  color: var(--text-muted);
  margin-top: 0.35rem;
}

.system-status {
  display: flex;
  align-items: center;
  gap: 0.5rem;
  font-size: 0.85rem;
  font-weight: 600;
  color: var(--accent-emerald);
  margin-bottom: 0.35rem;
  justify-content: flex-end;
}

.status-dot {
  width: 8px;
  height: 8px;
  border-radius: 50%;
  background-color: var(--accent-emerald);
  box-shadow: 0 0 8px var(--accent-emerald);
}

.copyright {
  font-size: 0.85rem;
  color: var(--text-muted);
}

/* --- Responsive Media Queries --- */
@media (max-width: 900px) {
  .nav-links {
    display: none;
    position: absolute;
    top: 4.5rem;
    left: 0;
    right: 0;
    flex-direction: column;
    background: var(--bg-primary);
    border-bottom: 1px solid var(--surface-border);
    padding: 1.5rem 2rem;
    box-shadow: var(--shadow-lg);
  }

  .nav-links.active {
    display: flex;
  }

  .mobile-menu-btn {
    display: flex;
  }

  .footer-container {
    flex-direction: column;
    text-align: center;
  }

  .system-status {
    justify-content: center;
  }
}

@media (max-width: 640px) {
  .hero-cta {
    flex-direction: column;
    width: 100%;
  }

  .hero-cta .btn {
    width: 100%;
  }

  .input-group {
    flex-direction: column;
    padding: 0.75rem;
  }

  .input-group input {
    margin-bottom: 0.5rem;
  }

  .input-group button {
    width: 100%;
  }

  .playground-card {
    padding: 1.25rem;
  }

  .code-content {
    font-size: 0.78rem;
    padding: 1rem;
  }
}

/**
 * Entire AI Test - Interactive Script
 * Features: Dark/Light Mode, Interactive Chat Simulation, Animated Counter, Mobile Menu
 */

document.addEventListener('DOMContentLoaded', () => {
  // 1. Theme Toggle (Dark / Light) with LocalStorage
  const themeToggle = document.getElementById('themeToggle');
  const htmlElement = document.documentElement;

  // Check saved theme preference or system preference
  const savedTheme = localStorage.getItem('entire-theme');
  const systemPrefersDark = window.matchMedia('(prefers-color-scheme: dark)').matches;

  if (savedTheme) {
    htmlElement.setAttribute('data-theme', savedTheme);
  } else if (!systemPrefersDark) {
    htmlElement.setAttribute('data-theme', 'light');
  }

  themeToggle.addEventListener('click', () => {
    const currentTheme = htmlElement.getAttribute('data-theme');
    const newTheme = currentTheme === 'dark' ? 'light' : 'dark';

    htmlElement.setAttribute('data-theme', newTheme);
    localStorage.setItem('entire-theme', newTheme);
  });

  // 2. Mobile Menu Navigation
  const mobileMenuBtn = document.getElementById('mobileMenuBtn');
  const navLinks = document.getElementById('navLinks');

  if (mobileMenuBtn && navLinks) {
    mobileMenuBtn.addEventListener('click', () => {
      navLinks.classList.toggle('active');
    });

    // Close menu when clicking any nav link
    navLinks.querySelectorAll('a').forEach(link => {
      link.addEventListener('click', () => {
        navLinks.classList.remove('active');
      });
    });
  }

  // 3. Dynamic Footer Year
  const currentYearSpan = document.getElementById('currentYear');
  if (currentYearSpan) {
    currentYearSpan.textContent = new Date().getFullYear();
  }

  // 4. Interactive AI Playground Simulation
  const promptForm = document.getElementById('promptForm');
  const promptInput = document.getElementById('promptInput');
  const chatWindow = document.getElementById('chatWindow');
  const chips = document.querySelectorAll('.chip');
  let isGenerating = false;

  // Sample AI Responses Map
  const cannedResponses = {
    "tentang": "Entire AI Test adalah representasi aplikasi antarmuka cerdas berbasis web statis. Dibangun tanpa dependensi berlebih, platform ini mengutamakan efisiensi pemuatan, desain responsif, dan interaktivitas yang mulus.",
    "teknologi": "Website ini memanfaatkan teknologi inti web: HTML5 semantik untuk struktur yang solid, CSS3 kustom (CSS Variables, Flexbox, CSS Grid, Glassmorphism), dan Vanilla JavaScript modern (ES6+) untuk logika interaktif tanpa runtime berat.",
    "css": "Berikut tips menulis CSS yang rapi:\n1. Manfaatkan CSS Custom Properties (Variables) untuk warna & spasi.\n2. Utamakan pendekatan Mobile-First dengan media query yang efisien.\n3. Gunakan clamp() untuk tipografi yang fluid di berbagai ukuran layar.",
    "kutipan": "\"Kecerdasan buatan bukan untuk menggantikan imajinasi manusia, melainkan menjadi kanvas yang memperluas batas kreativitas kita.\" — Entire AI",
    "default": "Pertanyaan menarik! Sebagai prototipe Entire AI Test, sistem telah memproses input Anda dengan sukses. Setiap komponen halaman ini siap dikembangkan lebih lanjut menjadi aplikasi web berskala penuh."
  };

  function getSmartResponse(userInput) {
    const query = userInput.toLowerCase();
    if (query.includes('tentang') || query.includes('entire')) {
      return cannedResponses.tentang;
    } else if (query.includes('teknologi') || query.includes('stack') || query.includes('bahasa')) {
      return cannedResponses.teknologi;
    } else if (query.includes('css') || query.includes('tips') || query.includes('rapi')) {
      return cannedResponses.css;
    } else if (query.includes('kutipan') || query.includes('quotes') || query.includes('mutiara')) {
      return cannedResponses.kutipan;
    }
    return cannedResponses.default;
  }

  function appendUserMessage(text) {
    const userDiv = document.createElement('div');
    userDiv.className = 'chat-message user-message';
    userDiv.innerHTML = `
      <div class="avatar">
        <svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2">
          <path d="M20 21v-2a4 4 0 0 0-4-4H8a4 4 0 0 0-4 4v2"></path>
          <circle cx="12" cy="7" r="4"></circle>
        </svg>
      </div>
      <div class="message-bubble">
        <p>${escapeHtml(text)}</p>
      </div>
    `;
    chatWindow.appendChild(userDiv);
    chatWindow.scrollTop = chatWindow.scrollHeight;
  }

  function appendBotMessage(fullText) {
    isGenerating = true;
    const botDiv = document.createElement('div');
    botDiv.className = 'chat-message bot-message';
    botDiv.innerHTML = `
      <div class="avatar">
        <svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2">
          <path d="M12 2a2 2 0 0 1 2 2v2a2 2 0 0 1-2 2 2 2 0 0 1-2-2V4a2 2 0 0 1 2-2z"></path>
          <rect x="4" y="8" width="16" height="12" rx="2"></rect>
          <circle cx="9" cy="13" r="1.5"></circle>
          <circle cx="15" cy="13" r="1.5"></circle>
          <path d="M10 17h4"></path>
        </svg>
      </div>
      <div class="message-bubble">
        <p class="bot-text"></p><span class="typing-cursor"></span>
      </div>
    `;
    chatWindow.appendChild(botDiv);
    chatWindow.scrollTop = chatWindow.scrollHeight;

    const textTarget = botDiv.querySelector('.bot-text');
    const cursor = botDiv.querySelector('.typing-cursor');
    let charIndex = 0;

    // Typewriter effect
    const interval = setInterval(() => {
      if (charIndex < fullText.length) {
        textTarget.textContent += fullText.charAt(charIndex);
        charIndex++;
        chatWindow.scrollTop = chatWindow.scrollHeight;
      } else {
        clearInterval(interval);
        cursor.remove();
        isGenerating = false;
      }
    }, 18);
  }

  function escapeHtml(string) {
    const div = document.createElement('div');
    div.innerText = string;
    return div.innerHTML;
  }

  function handleSendPrompt(text) {
    if (!text.trim() || isGenerating) return;

    appendUserMessage(text);
    promptInput.value = '';

    // Simulate short network delay before responding
    setTimeout(() => {
      const response = getSmartResponse(text);
      appendBotMessage(response);
    }, 350);
  }

  if (promptForm) {
    promptForm.addEventListener('submit', (e) => {
      e.preventDefault();
      handleSendPrompt(promptInput.value);
    });
  }

  chips.forEach(chip => {
    chip.addEventListener('click', () => {
      const promptText = chip.getAttribute('data-prompt');
      handleSendPrompt(promptText);
    });
  });

  // 5. Animated Stats Counter (Intersection Observer)
  const statsSection = document.querySelector('.stats-section');
  const statNumbers = document.querySelectorAll('.stat-number');
  let statsTriggered = false;

  function animateNumbers() {
    statNumbers.forEach(elem => {
      const target = parseFloat(elem.getAttribute('data-target'));
      const isDecimal = target % 1 !== 0;
      const duration = 1800; // ms
      const startTime = performance.now();

      function updateNumber(currentTime) {
        const elapsed = currentTime - startTime;
        const progress = Math.min(elapsed / duration, 1);

        // Ease out quadratic function
        const easeProgress = 1 - Math.pow(1 - progress, 3);
        const currentVal = easeProgress * target;

        if (isDecimal) {
          elem.textContent = currentVal.toFixed(1);
        } else {
          elem.textContent = Math.round(currentVal);
        }

        if (progress < 1) {
          requestAnimationFrame(updateNumber);
        } else {
          elem.textContent = target;
        }
      }

      requestAnimationFrame(updateNumber);
    });
  }

  if (statsSection) {
    const observer = new IntersectionObserver((entries) => {
      entries.forEach(entry => {
        if (entry.isIntersecting && !statsTriggered) {
          statsTriggered = true;
          animateNumbers();
        }
      });
    }, { threshold: 0.3 });

    observer.observe(statsSection);
  }
});
